def fizzbuzz(n: int) -> List[str]:
    """Devuelve una lista de strings del 1 al n siguiendo la lógica FizzBuzz."""
    resultado: List[str] = []
    for i in range(1, n + 1):
        s = str(i)
        if i % 3 == 0 and i % 5 == 0:
            resultado.append("FizzBuzz")
        elif i % 3 == 0:
