from typing import List

def buscar(lista: List[int], x: int) -> int:
    """Busca un elemento x en una lista ordenada usando búsqueda binaria."""
    izquierda = 0
    derecha = len(lista) - 1

    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        valor_medio = lista[medio]

        if valor_medio == x:
            return medio
        elif valor_medio < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1

    return -1

