def agrupar_por(items: List[Dict[str, Any]], clave: str) -> Dict[Any, List[Dict[str, Any]]]:
    """Agrupa una lista de diccionarios por el valor de una clave específica."""
    grupos: Dict[Any, List[Dict[str, Any]]] = {}
    for item in items:
        if clave in item:
