def contar_palabras(texto: str) -> Dict[str, int]:
    """Cuenta la frecuencia de cada palabra en un texto, ignorando mayúsculas y puntuación."""
    if not texto:
        return {}

    # Convertir a minúsculas y reemplazar cualquier cosa que no sea letra o espacio por un espacio
    texto_limpio = re.sub(r'[^\w\s]', ' ', texto.lower())

