def from_romano(s: str) -> int:
    """Convierte un número romano en mayúsculas a su entero correspondiente."""
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    i = 0
    n = len(s)
    while i < n:
        valor_actual = valores[s[i]]
        if i + 1 < n:
            valor_siguiente = valores[s[i+1]]
            if valor_actual < valor_siguiente:
                total += valor_siguiente - valor_actual
                i += 2
                continue
        total += valor_actual
        i += 1
    return total

