def mayor_racha(lista: List) -> Optional[Tuple]:
    """Encuentra la racha más larga de elementos consecutivos iguales y devuelve (elemento, longitud)."""
    if not lista:
        return None

    max_racha: Tuple[any, int] = (lista[0], 0)
    actual_racha_elemento = lista[0]
    actual_racha_longitud = 0

    for elemento in lista:
        if elemento == actual_racha_elemento:
            actual_racha_longitud += 1
        else:
            # Se rompió la racha anterior
            if actual_racha_longitud > max_racha[1]:
                max_racha = (actual_racha_elemento, actual_racha_longitud)

            # Reiniciar para la nueva racha
            actual_racha_elemento = elemento
            actual_racha_longitud = 1

    # Verificar la última racha después de salir del bucle
    if actual_racha_longitud > max_racha[1]:
        max_racha = (actual_racha_elemento, actual_racha_longitud)

    return max_racha

def a_camel(s: str) -> str:
    """Convierte un string de snake_case a camelCase."""
    if not s:
        return ""
    words = s.split('_')
    if not words:
        return ""

    first_word = words[0]
    capitalized_words = [word.capitalize() for word in words[1:]]

    return first_word + "".join(capitalized_words)

import re

def a_snake(s: str) -> str:
    """Convierte una cadena de camelCase o PascalCase a snake_case."""
    if not s:
        return ""
    # Reemplaza cualquier transición de minúscula a mayúscula o de mayúscula a mayúscula seguida de minúscula
    # por un guion bajo, asegurando que no haya guiones al inicio.
    s = re.sub(r'(?<!^)(?=[A-Z])', '_', s)
    return s.lower()

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    def es_primo(num: int) -> bool:
        if num < 2:
            return False
        i = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += 1
        return True

    return [num for num in range(2, n + 1) if es_primo(num)]

