def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones si resulta en una cadena más corta."""
    if not s:
        return s

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    compressed_parts = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 0
        j = i
        while j < len(s) and s[j] == char:
            count += 1
            j += 1
        compressed_parts.append(f"{char}{count}")
        i = j

    compressed_s = "".join(compressed_parts)

    return compressed_s if len(compressed_s) < len(s) else s

