        raise ValueError("La cantidad de bytes no puede ser negativa")

    unidades = ["B", "KB", "MB", "GB"]
    bytes_actuales = float(n)
    i = 0

    while bytes_actuales >= 1024 and i < len(unidades) - 1:
        bytes_actuales /= 1024.0
        i += 1

    if i == 0:
        return f"{int(n)} {unidades[0]}"
    else:
        # Para unidades mayores a B, se muestra con un decimal.
        # Para B, se muestra sin decimales (manejo en el if i == 0).
        return f"{bytes_actuales:.1f} {unidades[i]}"

