def binaria(lista: List[int], x: int) -> int:
    """Busca x en una lista ordenada usando búsqueda binaria y devuelve su índice, o -1 si no está."""
    bajo = 0
    alto = len(lista) - 1

    while bajo <= alto:
        medio = (bajo + alto) // 2
        valor_medio = lista[medio]

        if valor_medio == x:
            return medio
        elif valor_medio < x:
            bajo = medio + 1
        else:
            alto = medio - 1

    return -1

