from typing import List

def contar_islas(grid: List[List[int]]) -> int:
    """Cuenta el número de grupos de 1 conectados en una matriz de 0 y 1."""
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    island_count = 0

    def dfs(r: int, c: int):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if visited[r][c] or grid[r][c] == 0:
            return

        visited[r][c] = True
        # Vecinos: arriba, abajo, izquierda, derecha
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                island_count += 1
                dfs(r, c)

    return island_count

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m = len(a)
    n = len(b)

    if m == 0:
        return n
    if n == 0:
        return m

    # Inicializa la matriz de distancias
    # dp[i][j] es la distancia entre a[:i] y b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Casos base: costo de transformar una cadena vacía en la otra
    for i in range(m + 1):
        dp[i][0] = i  # Costo de borrar i caracteres de a
    for j in range(n + 1):
        dp[0][j] = j  # Costo de insertar j caracteres de b

    # Rellena la matriz
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            costo_sustitucion = 0 if a[i - 1] == b[j - 1] else 1

            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Borrar a[i-1]
                dp[i][j - 1] + 1,        # Insertar b[j-1]
                dp[i - 1][j - 1] + costo_sustitucion  # Sustituir o coincidir
            )

    return dp[m][n]

def a_base(n: int, base: int) -> str:
    """Convierte un entero no negativo a string en la base dada (2 a 16)."""
    if n < 0:
        raise ValueError("El entero debe ser no negativo.")
    if not (2 <= base <= 16):
        raise ValueError("La base debe estar entre 2 y 16.")
    if n == 0:
        return '0'

    DIGITS = "0123456789abcdef"
    resultado = ""
    while n > 0:
        resto = n % base
        resultado = DIGITS[resto] + resultado
        n //= base
    return resultado

