def con_reintentos(fn: Callable[[], T], veces: int) -> T:
    """Ejecuta una función con reintentos hasta 'veces' intentos."""
    if veces <= 0:
        raise ValueError("El número de veces debe ser positivo.")

    ultima_excepcion = None
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            ultima_excepcion = e
            if i < veces - 1:
                continue
            else:
                raise ultima_excepcion

